return ['domain'=>'blockstudio','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'kn','project-id-version'=>'Blockstudio','po-revision-date'=>'2026-10-23 15:32+0000','messages'=>['Blockstudio'=>'Blockstudio','The "%1$s" attribute on a %2$s block tag is dropped because the block declares no field with that id. Declare the field, or write it as a data-, aria- or html- attribute to put it on the root element.'=>'%2$s ಬ್ಲಾಕ್ ಟ್ಯಾಗ್‌ನಲ್ಲಿರುವ "%1$s" ಗುಣಲಕ್ಷಣವನ್ನು ಕೈಬಿಡಲಾಗಿದೆ, ಏಕೆಂದರೆ ಬ್ಲಾಕ್ ಆ ಐಡಿಯೊಂದಿಗೆ ಯಾವುದೇ ಕ್ಷೇತ್ರವನ್ನು ಘೋಷಿಸಿಲ್ಲ. ಕ್ಷೇತ್ರವನ್ನು ಘೋಷಿಸಿ, ಅಥವಾ ಅದನ್ನು data-, aria- ಅಥವಾ html- ಗುಣಲಕ್ಷಣವಾಗಿ ಬರೆದು ರೂಟ್ ಎಲಿಮೆಂಟ್‌ಗೆ ಸೇರಿಸಿ.','This storage key is not declared by the block or its extensions.'=>'ಈ ಸಂಗ್ರಹಣಾ ಕೀಲಿಯನ್ನು ಬ್ಲಾಕ್ ಅಥವಾ ಅದರ ವಿಸ್ತರಣೆಗಳು ಘೋಷಿಸಿಲ್ಲ.','This top-level key is not an attribute of the block, so it is ignored.'=>'ಈ ಮೇಲ್ಮಟ್ಟದ ಕೀಲಿ ಬ್ಲಾಕ್‌ನ ಗುಣಲಕ್ಷಣವಲ್ಲ, ಆದ್ದರಿಂದ ಅದನ್ನು ನಿರ್ಲಕ್ಷಿಸಲಾಗುತ್ತದೆ.','This key is only read inside the blockstudio object, which is missing.'=>'ಈ ಕೀಲಿಯನ್ನು blockstudio ಆಬ್ಜೆಕ್ಟ್‌ನ ಒಳಗೆ ಮಾತ್ರ ಓದಲಾಗುತ್ತದೆ; ಆ ಆಬ್ಜೆಕ್ಟ್ ಕಾಣೆಯಾಗಿದೆ.','This value is not among the field options.'=>'ಈ ಮೌಲ್ಯವು ಕ್ಷೇತ್ರದ ಆಯ್ಕೆಗಳಲ್ಲಿ ಇಲ್ಲ.','This value has an unsupported shape for the field.'=>'ಈ ಮೌಲ್ಯದ ಆಕಾರವು ಕ್ಷೇತ್ರಕ್ಕೆ ಬೆಂಬಲಿತವಾಗಿಲ್ಲ.','This repeater has fewer rows than its minimum.'=>'ಈ ಪುನರಾವರ್ತಕದಲ್ಲಿ ಕನಿಷ್ಠಕ್ಕಿಂತ ಕಡಿಮೆ ಸಾಲುಗಳಿವೆ.','This repeater has more rows than its maximum.'=>'ಈ ಪುನರಾವರ್ತಕದಲ್ಲಿ ಗರಿಷ್ಠಕ್ಕಿಂತ ಹೆಚ್ಚು ಸಾಲುಗಳಿವೆ.','This storage key has conflicting field definitions.'=>'ಈ ಸಂಗ್ರಹಣಾ ಕೀಲಿಗೆ ಪರಸ್ಪರ ಸಂಘರ್ಷಿಸುವ ಕ್ಷೇತ್ರ ವ್ಯಾಖ್ಯಾನಗಳಿವೆ.','The nested field value overrides this top-level value.'=>'ನೆಸ್ಟೆಡ್ ಕ್ಷೇತ್ರದ ಮೌಲ್ಯವು ಈ ಮೇಲ್ಮಟ್ಟದ ಮೌಲ್ಯವನ್ನು ಮೀರಿಸುತ್ತದೆ.','Extension bindings read this value only from blockstudio.attributes.'=>'ವಿಸ್ತರಣೆ ಬೈಂಡಿಂಗ್‌ಗಳು ಈ ಮೌಲ್ಯವನ್ನು blockstudio.attributes ನಿಂದ ಮಾತ್ರ ಓದುತ್ತವೆ.','Blockstudio field values must be stored in an object.'=>'Blockstudio ಕ್ಷೇತ್ರದ ಮೌಲ್ಯಗಳನ್ನು ಆಬ್ಜೆಕ್ಟ್‌ನಲ್ಲಿ ಸಂಗ್ರಹಿಸಬೇಕು.','Blockstudio is preparing its block cache. Please retry shortly.'=>'Blockstudio ತನ್ನ ಬ್ಲಾಕ್ ಕ್ಯಾಶ್ ಅನ್ನು ಸಿದ್ಧಪಡಿಸುತ್ತಿದೆ. ದಯವಿಟ್ಟು ಸ್ವಲ್ಪ ಸಮಯದ ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.','Canvas is disabled.'=>'ಕ್ಯಾನ್ವಾಸ್ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ.','Invalid or missing CSRF token.'=>'CSRF ಟೋಕನ್ ಅಮಾನ್ಯವಾಗಿದೆ ಅಥವಾ ಇಲ್ಲ.','Authentication required.'=>'ದೃಢೀಕರಣ ಅಗತ್ಯವಿದೆ.','Insufficient permissions.'=>'ಸಾಕಷ್ಟು ಅನುಮತಿಗಳಿಲ್ಲ.','Validation failed.'=>'ಮಾನ್ಯೀಕರಣ ವಿಫಲವಾಗಿದೆ.','Record not found.'=>'ದಾಖಲೆ ಕಂಡುಬಂದಿಲ್ಲ.','Invalid islands request.'=>'ದ್ವೀಪಗಳ ವಿನಂತಿ ಅಮಾನ್ಯವಾಗಿದೆ.','Too many islands requested.'=>'ಹೆಚ್ಚು ದ್ವೀಪಗಳನ್ನು ವಿನಂತಿಸಲಾಗಿದೆ.','Invalid island block.'=>'ದ್ವೀಪದ ಬ್ಲಾಕ್ ಅಮಾನ್ಯವಾಗಿದೆ.','Invalid island signature.'=>'ದ್ವೀಪದ ಸಹಿ ಅಮಾನ್ಯವಾಗಿದೆ.','Sorry, you are not allowed to read blocks of this post.'=>'ಕ್ಷಮಿಸಿ, ಈ ಪೋಸ್ಟ್‌ನ ಬ್ಲಾಕ್‌ಗಳನ್ನು ಓದಲು ನಿಮಗೆ ಅನುಮತಿಯಿಲ್ಲ.','Sorry, you are not allowed to read blocks as this user.'=>'ಕ್ಷಮಿಸಿ, ಈ ಬಳಕೆದಾರರಾಗಿ ಬ್ಲಾಕ್‌ಗಳನ್ನು ಓದಲು ನಿಮಗೆ ಅನುಮತಿಯಿಲ್ಲ.','Invalid block.'=>'ಬ್ಲಾಕ್ ಅಮಾನ್ಯವಾಗಿದೆ.','Method not allowed.'=>'ವಿಧಾನಕ್ಕೆ ಅನುಮತಿಯಿಲ್ಲ.','Block not found.'=>'ಬ್ಲಾಕ್ ಕಂಡುಬಂದಿಲ್ಲ.','Function not found.'=>'ಕಾರ್ಯ ಕಂಡುಬಂದಿಲ್ಲ.','Function is not callable.'=>'ಕಾರ್ಯವನ್ನು ಕರೆಯಲು ಸಾಧ್ಯವಿಲ್ಲ.','Blockstudio ignored invalid configuration values:'=>'Blockstudio ಅಮಾನ್ಯ ಸಂರಚನಾ ಮೌಲ್ಯಗಳನ್ನು ನಿರ್ಲಕ್ಷಿಸಿದೆ:','%s: Link text'=>'%s: ಲಿಂಕ್ ಪಠ್ಯ','%s: URL'=>'%s: URL','True'=>'ಸತ್ಯ','False'=>'ಸುಳ್ಳು','Could not load database records.'=>'ಡೇಟಾಬೇಸ್ ದಾಖಲೆಗಳನ್ನು ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.','This database has no records yet.'=>'ಈ ಡೇಟಾಬೇಸ್‌ನಲ್ಲಿ ಇನ್ನೂ ಯಾವುದೇ ದಾಖಲೆಗಳಿಲ್ಲ.','No Blockstudio databases are registered.'=>'ಯಾವುದೇ Blockstudio ಡೇಟಾಬೇಸ್‌ಗಳನ್ನು ನೋಂದಾಯಿಸಲಾಗಿಲ್ಲ.','The selected database could not be found.'=>'ಆಯ್ಕೆ ಮಾಡಿದ ಡೇಟಾಬೇಸ್ ಕಂಡುಬಂದಿಲ್ಲ.','Overview'=>'ಅವಲೋಕನ','Registry'=>'ನೋಂದಣಿ','Databases'=>'ಡೇಟಾಬೇಸ್‌ಗಳು','Docs'=>'ದಸ್ತಾವೇಜುಗಳು','No Blockstudio overview data is available.'=>'ಯಾವುದೇ Blockstudio ಅವಲೋಕನ ಡೇಟಾ ಲಭ್ಯವಿಲ್ಲ.','Name'=>'ಹೆಸರು','Title'=>'ಶೀರ್ಷಿಕೆ','Description'=>'ವಿವರಣೆ','Category'=>'ವರ್ಗ','Type'=>'